Content.Implementation:
(*Source selection for data to HMI*)

(* Check if LSP is in alarm*)
IF NOT LSP_B3_COM AND NOT LSPA_DISABLED_IN.stVal THEN 		//To check if LSP is disabled if values still need to be displayed and only outputs blocked
	LOCAL_LSP_GW_IN:=LSP_B3_TO_GW_B;
ELSIF NOT LSP_B_COM AND NOT LSPB_DISABLED_IN.stVal THEN
	LOCAL_LSP_GW_IN:=LSP_B_TO_GW_B;
END_IF


(*Check if GCS A is in alarm*)
IF NOT (GCS_B3_COM) AND (AGC_Enable_Status_A.stVal) THEN
	LOCAL_GCS_GW_IN:=NGVL_GCSB3_GW;
ELSIF NOT (GCS_B_COM) AND (AGC_Enable_Status_B.stVal) THEN
	LOCAL_GCS_GW_IN:=NGVL_GCSB_GW;
END_IF
